async function claimAlbum(seasonId,clubId){try{const d=await api('/api/album/claim',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({seasonId,clubId})});toast('Récompense récupérée · '+(d.reward?.coins||250)+' FOOTCOINS · '+(d.reward?.xp||75)+' XP');render()}catch(e){toast(e.message)}}async function cardDetail(id){try{const d=await api('/api/collection');state.user=d.user;const c=(d.cards||[]).find(x=>x.instanceId===id);if(!c)throw new Error('Carte introuvable.');const base=Number(c.ovr)||72;const labels=cardStatDefinitions(c.position);const stats=labels.map(([x,k])=>({x,v:Math.max(1,Math.min(99,Number(c[k]||base)))})),ov=base,value=rarityValue[c.rarity]+Math.max(0,ov-base)*25;return `<div class="page card-detail-page"><a class="card-detail-close" href="#vault" aria-label="Fermer">×</a>${viewHero('FOOTVAULT / PLAYER CARD',esc(c.name),'Carte unique de ta collection.') }<div class="detail-layout"><div class="detail-card">${cardMarkup(c)}</div><div class="detail-copy"><p class="eyebrow">ATTRIBUTS</p><h2>${esc(c.name)}</h2><p class="lead">Une carte ${esc(c.rarityLabel).toLowerCase()} de ${esc(c.club)}. Profil évalué à ${ov} OVR.</p><div class="facts"><div class="fact"><span>CLUB</span><strong>${esc(c.club)}</strong></div><div class="fact"><span>NATION</span><strong>${esc(c.nation)}</strong></div><div class="fact"><span>POSTE</span><strong>${esc(c.position)}</strong></div><div class="fact"><span>SAISON</span><strong>${esc(c.season)}</strong></div><div class="fact"><span>TYPE</span><strong>${c.isLimited?`LIMITED · ${esc(c.serialLabel||'—')}`:'STANDARD'}</strong></div><div class="fact"><span>SOURCE</span><strong>${String(c.source||'VAULT').startsWith('pack:')?'PACK':esc(c.source)}</strong></div></div><div class="panel"><div style="display:flex;justify-content:space-between"><span class="eyebrow">SIX ATTRIBUTS</span><strong style="font:900 28px var(--head);color:var(--gold2)">${ov} OVR</strong></div>${stats.map(s=>`<div class="stat-row"><span>${s.x}</span><div class="stat-track"><i style="width:${s.v}%"></i></div><strong>${s.v}</strong></div>`).join('')}</div><div class="value"><span>VAULT VALUE</span><strong>${money(value)} FC</strong><small>Valeur interne selon rareté et profil. Pas encore un prix de marché.</small></div><div class="panel" style="margin-top:12px"><div class="fact" style="border:0;padding:0"><span>ACQUISE LE</span><strong>${new Date(c.acquiredAt).toLocaleDateString('fr-FR')}</strong></div></div></div></div></div>`}catch(e){if(e.status===401)return authView('login','card?id='+encodeURIComponent(id));return `<div class="page"><div class="empty">${esc(e.message)}</div></div>`}}
